from jsonb_to_recordset($json$[{"id":"che-st-111","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Avogadro’s constant $N_A$ is accepted as approximately","options":["$6.022 \\times 10^{23}\\ \\mathrm{mol^{-1}}$","$6.022 \\times 10^{22}\\ \\mathrm{mol^{-1}}$","$3.011 \\times 10^{23}\\ \\mathrm{mol^{-1}}$","$1.602 \\times 10^{-19}\\ \\mathrm{mol^{-1}}$"],"answer_index":0,"explanation":"One mole contains $6.022 \\times 10^{23}$ specified elementary entities.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-112","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The SI mole is defined so that 12 g of the carbon-12 nuclide contains","options":["one atom of carbon-12","$6.022 \\times 10^{23}$ carbon-12 atoms","12 carbon-12 atoms","$12 \\times 6.022 \\times 10^{23}$ atoms"],"answer_index":1,"explanation":"By definition, 12 g of $^{12}\\mathrm{C}$ is 1 mol and therefore holds $N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-113","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The amount of substance $n$ and the number of elementary entities $N$ are linked by","options":["$n = N \\times N_A$","$n = N / N_A$","$n = N_A / N$","$n = N + N_A$"],"answer_index":1,"explanation":"Dividing the particle count by Avogadro’s constant converts it to moles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-114","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One unified atomic mass unit (1 u) is defined as","options":["the mass of one hydrogen atom","one-twelfth of the mass of a carbon-12 atom","the mass of one oxygen-16 atom","1 g exactly"],"answer_index":1,"explanation":"The u (or amu) is $1/12$ of the mass of a single $^{12}\\mathrm{C}$ atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-115","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Gram-atomic mass of an element is the mass, in grams, of","options":["one atom of the element","one mole of its atoms","one molecule only","Avogadro’s number of molecules of any compound"],"answer_index":1,"explanation":"The gram-atomic mass is numerically equal to the atomic mass and is the mass of $N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-116","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"At 273 K and 1 atm (classic STP), the molar volume of an ideal gas is taken in Intermediate tables as","options":["11.2 L","22.4 L","24.0 L","44.8 L"],"answer_index":1,"explanation":"One mole of ideal gas occupies 22.4 L at 273 K and 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-117","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A pair of samples that must contain the same number of molecules is","options":["1 mol of $\\mathrm{O_2}$ and 1 mol of $\\mathrm{O_3}$","16 g of $\\mathrm{O_2}$ and 16 g of $\\mathrm{O_3}$","1 mol of $\\mathrm{O_2}$ and 2 mol of $\\mathrm{He}$","22.4 L of $\\mathrm{H_2}$ at STP and 11.2 L of $\\mathrm{He}$ at STP"],"answer_index":0,"explanation":"Equal amounts in moles contain equal numbers of molecules, whatever the formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-118","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Half a mole of dioxygen molecules contains oxygen atoms numbering","options":["$0.5\\,N_A$","$N_A$","$2\\,N_A$","$0.25\\,N_A$"],"answer_index":1,"explanation":"Each $\\mathrm{O_2}$ molecule has two atoms, so $0.5\\,N_A$ molecules hold $N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-119","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The numerical value $1.66 \\times 10^{-24}$ g is the approximate mass of","options":["one mole of protons","one unified atomic mass unit","one electron","one mole of $^{12}\\mathrm{C}$"],"answer_index":1,"explanation":"1 u $\\approx 1.66 \\times 10^{-24}$ g, which is $1/N_A$ grams.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-120","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Twelve grams of carbon-12 and eighteen grams of water both represent","options":["the same number of atoms","one mole of the stated substance","two moles of molecules","half a mole of each"],"answer_index":1,"explanation":"12 g of $^{12}\\mathrm{C}$ is 1 mol of atoms; 18 g of $\\mathrm{H_2O}$ is 1 mol of molecules.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
